// Sheet AI 3x2 đã key nền xanh (chỉ giữ mảng lớn nhất giữa mỗi ô) -> WebP base64
export const RAT_ART = 'data:image/webp;base64,';
export const ratPos = (i: number) => ({
  backgroundImage: `url(${RAT_ART})`,
  backgroundSize: '300% 200%',
  backgroundPosition: `${(i % 3) * (100 / (3 - 1))}% ${(Math.floor(i / 3)) * (100 / (2 - 1))}%`,
});
